#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Fly.io account, app, secrets and deploy token (issue #104).
# Secret values are typed hidden and piped straight to 'fly secrets import' on stdin: they are
# never written to disk, never put on a command line, and never printed.
# ──────────────────────────────────────────────────────────────────────────

APP_NAME="postszn-api"

run_wizard() {

ENV_FILE="${ENV_FILE:-$HOME/.config/postszn-wizards/fly.env}"
mkdir -p "$(dirname "$ENV_FILE")"
SUPABASE_ENV="$HOME/.config/postszn-wizards/supabase-prod.env"
# shellcheck disable=SC1090
[[ -f "$SUPABASE_ENV" ]] && . "$SUPABASE_ENV"

TOTAL_STAGES=7

banner "Fly.io API app, secrets and first deploy (#104)"
note "Run from the repository root after supabase-prod.sh. Needs a card on the Fly account."
note "Secrets are typed hidden and sent to Fly on stdin; nothing secret is stored here."
[[ -f fly.toml ]] || { warn "Run this from the repository root (fly.toml not found)."; exit 1; }
pause "Press Enter to begin"

stage "Fly account, billing and flyctl"
open_url "https://fly.io/app/sign-up"
step "Create the account (or sign in). Add a card under Billing: the machine is not free."
open_url "https://fly.io/dashboard/personal/billing"
if command -v fly >/dev/null 2>&1; then
  say "flyctl found: $(fly version 2>/dev/null | head -n1)"
else
  open_url "https://fly.io/docs/flyctl/install/"
  step "Install flyctl, open a new terminal, and re-run this wizard."
  exit 1
fi
fly auth whoami >/dev/null 2>&1 || fly auth login
say "Signed in as: $(fly auth whoami)"

stage "Create the app"
say "App name comes from fly.toml: $APP_NAME. Region there is 'iad'; if your Supabase region is elsewhere"
say "(see docs/deploy/fly.md) edit primary_region in fly.toml in a pull request BEFORE the first deploy."
if fly apps list 2>/dev/null | awk '{print $1}' | grep -qx "$APP_NAME"; then
  say "App $APP_NAME already exists; keeping it."
else
  confirm "Create Fly app $APP_NAME now?" && fly apps create "$APP_NAME" || { warn "App not created; stopping."; exit 1; }
fi

stage "Non-secret settings"
say "These are not sensitive. Enter keeps the value shown in brackets."
# Prefill so Enter accepts a sensible value; ask shows whatever is already in $ENV_FILE.
[[ -n "$(_existing SUPABASE_URL || true)" || -z "${SUPABASE_URL:-}" ]] || write_env SUPABASE_URL "$SUPABASE_URL"
[[ -n "$(_existing CORS_ORIGINS || true)" ]] || write_env CORS_ORIGINS "https://postsznfantasy.com"
[[ -n "$(_existing RAPIDAPI_BASEURL || true)" ]] || write_env RAPIDAPI_BASEURL "https://tank01-nfl-live-in-game-real-time-statistics-nfl.p.rapidapi.com"
[[ -n "$(_existing RAPIDAPI_APIHOST || true)" ]] || write_env RAPIDAPI_APIHOST "tank01-nfl-live-in-game-real-time-statistics-nfl.p.rapidapi.com"
ask SUPABASE_URL "Supabase project URL (https://<ref>.supabase.co):"
write_env SUPABASE_URL "$SUPABASE_URL"
ask CORS_ORIGINS "Allowed browser origin(s), comma-separated:"
write_env CORS_ORIGINS "$CORS_ORIGINS"
ask RAPIDAPI_BASEURL "RapidAPI base URL (tank01 ... .p.rapidapi.com, with https://):"
write_env RAPIDAPI_BASEURL "$RAPIDAPI_BASEURL"
ask RAPIDAPI_APIHOST "RapidAPI host (same host without https://):"
write_env RAPIDAPI_APIHOST "$RAPIDAPI_APIHOST"
note "SCHEDULER_ENABLED is staged as false; the cutover runbook says when to turn it on."

stage "Secrets: database and RapidAPI key"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF:-_}/database/settings"
step "Copy the DIRECT connection string (db.<ref>.supabase.co:5432) and insert the real password."
warn "Never the transaction pooler (port 6543). If you later find Fly cannot reach the direct host (IPv6), use the session pooler string instead."
while :; do
  ask_secret PG_URI "Paste PG_URI (hidden):"
  [[ "$PG_URI" == *":6543"* ]] && { warn "Port 6543 is not allowed."; continue; }
  break
done
open_url "https://rapidapi.com/developer/apps"
step "Open your app, copy the key (X-RapidAPI-Key)."
ask_secret RAPIDAPI_APIKEY "Paste the RapidAPI key (hidden):"
say "Staging the secrets on Fly (no restart; the machine does not exist until the first deploy)..."
if printf 'PG_URI=%s\nRAPIDAPI_APIKEY=%s\nSUPABASE_URL=%s\nCORS_ORIGINS=%s\nRAPIDAPI_BASEURL=%s\nRAPIDAPI_APIHOST=%s\nSCHEDULER_ENABLED=false\n' \
    "$PG_URI" "$RAPIDAPI_APIKEY" "$SUPABASE_URL" "$CORS_ORIGINS" "$RAPIDAPI_BASEURL" "$RAPIDAPI_APIHOST" \
    | fly secrets import --stage --app "$APP_NAME"; then
  say "Secrets now set on Fly (names only):"
  fly secrets list --app "$APP_NAME"
else
  SKIPPED+=("Set the Fly secrets by hand: see docs/deploy/fly.md, section Secrets")
  warn "fly secrets import failed; see the message above"
fi
unset PG_URI RAPIDAPI_APIKEY

stage "GitHub secret: FLY_API_TOKEN"
say "A deploy-only token scoped to $APP_NAME, sent directly to GitHub; it is never shown."
if token=$(fly tokens create deploy --app "$APP_NAME" 2>/dev/null) && [[ -n "$token" ]]; then
  set_secret FLY_API_TOKEN "$token"
  unset token
else
  SKIPPED+=("Create the token: fly tokens create deploy --app $APP_NAME, then: gh secret set FLY_API_TOKEN")
fi
note "PROD_DATABASE_URL is set by supabase-prod.sh; BACKUP_GPG_PUBLIC_KEY by the backup setup in docs/deploy/backup.md."

stage "First deploy"
say "Deploys go only through the 'Deploy API' GitHub workflow (it checks for live drafts and runs migrations first)."
say "The workflow must be on the default branch, so merge the deploy PR first."
if confirm "Trigger the Deploy API workflow now (no live drafts exist)?"; then
  gh workflow run deploy-api.yml -f confirm_no_live_draft=true && say "Started. Watch it: gh run watch"
  pause "Press Enter once the run has finished green"
else
  SKIPPED+=("Run the Deploy API workflow from the GitHub Actions tab")
fi

stage "Verify"
say "One machine, check passing:"
fly status --app "$APP_NAME" || true
say "Health (queries the database, so this also proves the Supabase connection):"
curl -s --max-time 10 "https://${APP_NAME}.fly.dev/api" || warn "no answer yet"
echo
step "Outbound IPv6 to Supabase: no 'network is unreachable' lines in: fly logs --app $APP_NAME"
SKIPPED+=("Next: scripts/wizards/cloudflare-pages.sh (adds the api.postsznfantasy.com certificate and DNS)")
finish
}

run_wizard "$@"; exit
